import fs from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
import { readCommerceMigration } from '../server/commerce/migrationSource.js';

export async function buildInventoryTitlesSql() {
  const { sql, checksum, acceptedChecksums } = await readCommerceMigration(9);
  const hashes = acceptedChecksums.map(hash => `'${hash}'`).join(',');
  return `-- Stocky Studio: run this COMPLETE file in the Stocky project's Supabase SQL Editor.
-- Generated by npm run commerce:titles:schema:sql; no credentials or inventory changes.
-- Existing fichas follow Stocky's current name. Stored titles remain as fallback.
BEGIN;
SET LOCAL search_path = public, pg_catalog;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '45s';
DO $inventory_titles$
DECLARE previous_checksum text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('stocky:commerce:migration'));
  IF to_regclass('public.commercial_products') IS NULL OR to_regclass('public.commerce_schema_migrations') IS NULL THEN
    RAISE EXCEPTION 'COMMERCE_FOUNDATION_REQUIRED';
  END IF;
  SELECT checksum INTO previous_checksum FROM public.commerce_schema_migrations WHERE version=9;
  IF FOUND THEN
    IF NOT (previous_checksum = ANY(ARRAY[${hashes}])) THEN
      RAISE EXCEPTION 'MIGRATION_CHECKSUM_MISMATCH: version 9';
    END IF;
  ELSE
${sql.trimEnd()}
    INSERT INTO public.commerce_schema_migrations(version,checksum) VALUES(9,'${checksum}');
  END IF;
END
$inventory_titles$;
COMMIT;
SELECT version,applied_at FROM public.commerce_schema_migrations WHERE version=9;
`;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const file = new URL('../docs/fullmatch/SUPABASE_INVENTORY_TITLES.sql', import.meta.url);
  const sql = await buildInventoryTitlesSql();
  if (process.argv.includes('--check')) {
    if ((await fs.readFile(file, 'utf8')).replace(/\r\n/g, '\n') !== sql) throw new Error('INVENTORY_TITLES_SQL_OUTDATED');
    console.log('Inventory titles SQL matches migration 9.');
  } else {
    await fs.writeFile(file, sql);
    console.log('Generated docs/fullmatch/SUPABASE_INVENTORY_TITLES.sql (no database connection).');
  }
}
